mapper.select:
select oc.id as id,oc.create_time as createTime,oc.role_code as roleCode,oc.post_id as postId,oc.score as score,oc.images as images,oc.order_id as orderId, oc.user_id as userId,oc.post_user_id as postUserId,oc.content as content, jp.title as title,jp.phone as contact, su.nickname as userName,su.avatar as userAvatar,su.phone as userPhone, boss.nickname as bossName,boss.avatar as bossAvatar,boss.phone as bossPhone, ev.score as userScore, ev2.score as bossScore from job_evaluate_log oc left join job_post jp on jp.id=oc.post_id left join sys_user su on su.id=oc.user_id left join sys_user boss on boss.id=oc.post_user_id left join job_evaluate ev on ev.user_id = oc.user_id and ev.role_code='member' left join job_evaluate ev2 on ev2.user_id = oc.post_user_id and ev2.role_code='company' WHERE 1=1
AND oc.user_id = #{params.userId}
AND oc.score = #{params.score}
AND oc.post_user_id = #{params.postUserId}
AND oc.role_code = #{params.roleCode}
and oc.create_time >= #{params.startDate} and oc.create_time <= #{params.endDate}
and ( jp.title like CONCAT('%',#{params.keyword},'%') or jp.descr like CONCAT('%',#{params.keyword},'%') or su.nickname like CONCAT('%',#{params.keyword},'%') or boss.nickname like CONCAT('%',#{params.keyword},'%') )
order by oc.create_time desc

